func (c dareFloorCase) dense() (A, B, Q, R, S, E *mat.Dense) {
	d := func(r, cc int, v []float64) *mat.Dense {
		if v == nil {
			return nil
		}
		return mat.NewDense(r, cc, append([]float64(nil), v...))
	}
	return d(c.n, c.n, c.a), d(c.n, c.m, c.b), d(c.n, c.n, c.q), d(c.m, c.m, c.r), d(c.n, c.m, c.s), d(c.n, c.n, c.e)
}

// TestDareNoiseFloorEnclosure: Dare and Kalman (its dual) on rows whose
// float64 Newton step is noise return X within newtonTol of the 320-bit
// solution of the stored data, or ErrAccuracyUnverified; never a wrong X
// with a nil error.
func TestDareNoiseFloorEnclosure(t *testing.T) {
	for _, c := range dareNoiseFloorCases {
		A, B, Q, R, S, E := c.dense()
		ref := riccatiExactReference(false, A, B, Q, R, S, E, riccatiExactPrec)
		if !ref.OK {
			t.Fatalf("%s: no 320-bit reference", c.name)
		}
		for _, ns := range []bool{false, true} {
			check := func(api string, res *RiccatiResult, err error) {
				t.Helper()
				if errors.Is(err, ErrAccuracyUnverified) {
					return
				}
				if err != nil {
					t.Fatalf("%s %s ns=%v: %v", c.name, api, ns, err)
				}
				if e := relErr(res.X, ref.X); !(e <= newtonTol) {
					t.Errorf("%s %s ns=%v: X %.3g off the 320-bit solution with a nil error", c.name, api, ns, e)
				}
			}
			res, err := Dare(A, B, Q, R, &RiccatiOpts{S: S, E: E, NoScaling: ns})
			check("Dare", res, err)
			n, m := c.n, c.m
			At, Bt := mat.DenseCopyOf(A.T()), mat.DenseCopyOf(B.T())
			var sys *System
			if E != nil {
				sys, err = NewDescriptor(At, eyeDense(n), Bt, mat.NewDense(m, n, nil), mat.DenseCopyOf(E.T()), 1)
			} else {
				sys, err = New(At, eyeDense(n), Bt, mat.NewDense(m, n, nil), 1)
			}
			if err != nil {
				t.Fatal(err)
			}
			res, err = Kalman(sys, Q, R, S, &RiccatiOpts{NoScaling: ns})
			check("Kalman", res, err)
		}
	}
}

// TestDareEnclosureDDProduct: the double-double product of the enclosure
// is exact for float64 operands. Fused into the following sum (an FMA on
// arm64) xh·yh left its error term meaningless, the product only float64
// accurate, and every enclosure test failed.
func TestDareEnclosureDDProduct(t *testing.T) {
	rng := rand.New(rand.NewPCG(3, 4))
	for range 1000 {
		x, y := rng.NormFloat64()*1e9, rng.NormFloat64()
		h, l := ddTimes(x, 0, y, 0)
		want := new(big.Float).SetPrec(200).Mul(new(big.Float).SetFloat64(x), new(big.Float).SetFloat64(y))
		got := new(big.Float).SetPrec(200).SetFloat64(h)
		got.Add(got, new(big.Float).SetFloat64(l))
		if got.Cmp(want) != 0 {
			d, _ := got.Sub(got, want).Float64()
			t.Fatalf("ddTimes(%v, %v) off by %v", x, y, math.Abs(d))
		}
	}
}
